def D(name_te, kind, symptoms, cause, mild, moderate, urgent, prevent, src=SRC_TNAU, high_risk=False, name_en=None):
    return dict(disease_te=name_te, type=kind, symptoms_te=symptoms, cause_te=cause,
                steps=dict(mild=mild, moderate=moderate, urgent=urgent),
                prevention_te=prevent, source=src, high_risk=high_risk)

